#pragma once

#include <stdint.h>

// A glyph's pixels are 4-bit coverage (0 to 15), row after row, two to a
// byte (fonts.c, generated by `mise run fonts` from Barlow Condensed).
typedef struct {
    uint16_t bitmap_offset;
    uint8_t width, height, x_advance;
    int8_t x_offset, y_offset;
} glyph_t;

// first to last are the codes it holds, 127 the degree sign; y_advance is
// its line height, cap the height of its digits above the baseline (what
// text is centered on).
typedef struct {
    const uint8_t *bitmap;
    const glyph_t *glyphs;
    uint8_t first, last, y_advance, cap;
} font_t;

// Barlow Condensed, the Android app's font, at the sizes the pages use,
// big enough to read on a 2" panel from the seat: small (medium 18:
// what's dim, the scale's ends, help), label (semibold 20, letter-spaced:
// what a reading is), text (semibold 22: the strip, units, the settings'
// rows, lines), value (bold 34: a row's reading, a title), large (bold
// 50: a smaller dial's reading), big (bold 72, digits and units only: the
// oil's and a gauge alone's reading), huge (bold 104, digits, N, SHIFT:
// the gear on track, the oil too hot, the limiter).
extern const font_t font_small, font_label, font_text, font_value, font_large, font_big, font_huge;
